export const presets=[
['DITHER // INDEX','DITHER',.72,3,1.4,0.2,0],['DITHER // GHOST','DITHER',.88,5,1.1,.35,1],['HALFTONE // PRESS','PRINT',.85,5,1.25,.3,2],['RISO // OFFSET','PRINT',.77,3,1.3,.52,3],['XEROX // BURN','PRINT',.9,4,2.1,.44,4],['CHROME // BLEED','COLOR',.76,2,1.45,.42,5],['THERMAL // FIELD','COLOR',.92,3,1.3,.26,6],['LIQUID // WARP','DISTORT',.76,6,1.15,.95,7],['CRT // TEAR','DIGITAL',.85,3,1.4,.7,8],['DATA // SLICE','DIGITAL',.9,7,1.3,.85,9],['CONTOUR // BURN','EXPERIMENTAL',.86,3,1.8,.3,10],['DUOTONE // DAMAGE','COLOR',.85,4,1.5,.4,11]
].map(([name,category,amount,scale,contrast,distortion,mode],i)=>({id:`fx${i}`,name,category,amount,scale,contrast,distortion,mode,seed:17+i*13,enabled:true}));
export const clonePreset=p=>({...p,uid:crypto.randomUUID(),enabled:true});
const clamp=x=>Math.max(0,Math.min(255,x));
const fract=x=>x-Math.floor(x);
const hash=(x,y,s)=>fract(Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453);
export function processEffect(source,fx){const w=source.width,h=source.height;const input=source.data,out=new ImageData(w,h);const d=out.data;const {mode,amount,scale,contrast,distortion,seed}=fx;const get=(x,y,c)=>input[(Math.max(0,Math.min(h-1,y|0))*w+Math.max(0,Math.min(w-1,x|0)))*4+c];const cell=Math.max(1,Math.round(scale));for(let y=0;y<h;y++)for(let x=0;x<w;x++){let j=(y*w+x)*4;let dx=x,dy=y;const n=hash(Math.floor(x/cell),Math.floor(y/cell),seed);if([7,8,9].includes(mode)){dx=x+Math.sin(y/(mode===9?cell*4:25)+seed)*distortion*(mode===7?26:11)+(n-.5)*distortion*15;dy=y+(mode===7?Math.cos(x/30+seed)*distortion*22:0)}let r=get(dx,dy,0),g=get(dx,dy,1),b=get(dx,dy,2),a=get(dx,dy,3);const lum=(r*.299+g*.587+b*.114);const l=clamp((lum-128)*contrast+128);let R=r,G=g,B=b;const threshold=(n-.5)*distortion*90;switch(mode){case 0:case 1:{const m=mode===0?((x%4)*4+(y%4)):hash(Math.floor(x/cell),Math.floor(y/cell),seed)*16;const v=l/255+(m/16-.5)*amount*.65;const q=Math.round(Math.max(0,Math.min(1,v))*(mode===0?1:2))/(mode===0?1:2)*255;R=G=B=q;break}case 2:{const px=(x%Math.max(2,cell*2))/(cell*2)-.5,py=(y%Math.max(2,cell*2))/(cell*2)-.5;const dot=Math.sqrt(px*px+py*py)<(1-l/255)*.52;R=G=B=dot?15:245;break}case 3:{R=clamp(l*.85+45);G=clamp(l*.25+75);B=clamp(185-l*.45);if(n>.55){R=clamp(R+distortion*80);G=clamp(G-35)}break}case 4:{const v=l+threshold+hash(x,y,seed)*50-30>125?238:12;R=G=B=v;break}case 5:{R=clamp(l*.6+Math.sin(l/36)*80+65);G=clamp(l*.7+Math.sin(l/40+2)*65+50);B=clamp(l*.9+Math.cos(l/44)*70+40);break}case 6:{const t=l/255;R=clamp(255*Math.min(1,t*2.1));G=clamp(255*Math.max(0,1-Math.abs(t-.55)*2.3));B=clamp(255*Math.max(0,1-t*1.7));break}case 7:{R=get(dx+distortion*6,dy,0);G=g;B=get(dx-distortion*6,dy,2);break}case 8:{const scan=y%3===0?.64:1;R=clamp(get(dx+distortion*5,dy,0)*scan);G=clamp(g*scan);B=clamp(get(dx-distortion*5,dy,2)*scan);break}case 9:{R=get(dx+distortion*8,dy,0);G=g;B=get(dx-distortion*9,dy,2);break}case 10:{const edge=Math.abs(l-(get(x+2,y,0)*.299+get(x+2,y,1)*.587+get(x+2,y,2)*.114))+Math.abs(l-(get(x,y+2,0)*.299+get(x,y+2,1)*.587+get(x,y+2,2)*.114));R=clamp(edge*contrast*3+threshold);G=clamp(R*.34);B=clamp(R*.42);break}case 11:{const t=l>125+threshold;R=t?226:50;G=t?214:12;B=t?195:32;break}}const blend=amount;d[j]=clamp(r*(1-blend)+R*blend);d[j+1]=clamp(g*(1-blend)+G*blend);d[j+2]=clamp(b*(1-blend)+B*blend);d[j+3]=a}return out}
